(5861532, 852405, 15355, '<td valign="top">Very Cute!</td>', 'Very Cute!', '2010-02-10 08:52:08.000000', NULL, 1),
(5861697, 852578, 61961, '<td valign="top">I like it despite the fussy frame.</td>', 'I like it despite the fussy frame.', '2010-02-10 10:44:48.000000', NULL, 1),
(5861780, 852754, 28427, '<td valign="top">I like the complete set-up. Even the distortion in the floor doesn''t bother me.</td>', 'I like the complete set-up. Even the distortion in the floor doesn''t bother me.', '2010-02-10 12:04:29.000000', NULL, 1),
(5861783, 852715, 28427, '<td valign="top">Different approach of the theme.  At first I thought "what the..." but your title supports the image.  Otherwise I think you would have received some DNMC notes. *8* for being different.</td>', 'Different approach of the theme.  At first I thought "what the..." but your title supports the image.  Otherwise I think you would have received some DNMC notes. *8* for being different.', '2010-02-10 12:06:51.000000', NULL, 1),
(5861787, 852028, 28427, '<td valign="top">Simple, clean - less is definitely more *10*</td>', 'Simple, clean - less is definitely more *10*', '2010-02-10 12:09:47.000000', NULL, 1),
(5861796, 852621, 28427, '<td valign="top">Nice arrangement, great dog with the cutest face... Except for the backdrop: the folds are somehow attracting my eyes to it.  Even though you''ve ironed it so well.</td>', 'Nice arrangement, great dog with the cutest face... Except for the backdrop: the folds are somehow attracting my eyes to it.  Even though you''ve ironed it so well.', '2010-02-10 12:15:43.000000', NULL, 1),
