(5861869, 852283, 112177, '<td valign="top">This would have been good in the perspective challenge, very nice.</td>', 'This would have been good in the perspective challenge, very nice.', '2010-02-10 13:05:47.000000', NULL, 1),
(5861870, 852595, 83313, '<td valign="top">Creative, funny and well done. Three things that combine for a nice high vote from me.</td>', 'Creative, funny and well done. Three things that combine for a nice high vote from me.', '2010-02-10 13:06:08.000000', NULL, 1),
(5861871, 852742, 112177, '<td valign="top">This would have been perspective</td>', 'This would have been perspective', '2010-02-10 13:06:24.000000', NULL, 1),
(5861878, 852225, 112177, '<td valign="top">This is a greeting card just begging to be mailed.</td>', 'This is a greeting card just begging to be mailed.', '2010-02-10 13:08:30.000000', NULL, 1),
(5861881, 852720, 83313, '<td valign="top">I guess after a long day of war-mongering, he needs a place to sit and rest. The presence of the chair does not really add anything to this scene. It would be the same without it.</td>', 'I guess after a long day of war-mongering, he needs a place to sit and rest. The presence of the chair does not really add anything to this scene. It would be the same without it.', '2010-02-10 13:09:57.000000', NULL, 1),
(5861886, 852739, 112177, '<td valign="top">This would have been interesting to see in the perspective category. Very nice</td>', 'This would have been interesting to see in the perspective category. Very nice', '2010-02-10 13:12:58.000000', NULL, 1),
(5861887, 852715, 83313, '<td valign="top">This is a darn cool looking abstract, but I''m trying hard to see how it fits the topic. Perhaps this is the view seen by an elderly person from their front porch rocking chair? I may have to come back to this one later.</td>', 'This is a darn cool looking abstract, but I''m trying hard to see how it fits the topic. Perhaps this is the view seen by an elderly person from their front porch rocking chair? I may have to come back to this one later.', '2010-02-10 13:12:58.000000', NULL, 1),
(5861894, 852612, 112177, '<td valign="top">So cool, I can just imagine faeries and gnomes in this setting.</td>', 'So cool, I can just imagine faeries and gnomes in this setting.', '2010-02-10 13:14:53.000000', NULL, 1),
(5861895, 852738, 83313, '<td valign="top">I guess that title describes the processing as well as the perspective. I''m not sure if it will have high scoring mass appeal, but I think it does work for this scene.</td>', 'I guess that title describes the processing as well as the perspective. I''m not sure if it will have high scoring mass appeal, but I think it does work for this scene.', '2010-02-10 13:15:11.000000', NULL, 1),
(5861900, 852100, 83313, '<td valign="top">Nice semi-abstract approach to the topic. I''m not even sure what angle I am looking at this from.</td>', 'Nice semi-abstract approach to the topic. I''m not even sure what angle I am looking at this from.', '2010-02-10 13:16:58.000000', NULL, 1),
(5861902, 852612, 83313, '<td valign="top">What a neat find!</td>', 'What a neat find!', '2010-02-10 13:19:04.000000', NULL, 1),
(5861908, 852337, 83313, '<td valign="top">Wow, that''s even bigger than <a href="//www.dpchallenge.com/image.php?IMAGE_ID=779641" rel="nofollow" target="_blank">the one near me</a>!</td>', 'Wow, that''s even bigger than the one near me!', '2010-02-10 13:20:50.000000', NULL, 1),
(5861909, 851991, 83313, '<td valign="top">A simple and bold semi-abstract view. I like it.</td>', 'A simple and bold semi-abstract view. I like it.', '2010-02-10 13:23:18.000000', NULL, 1),
(5861911, 852711, 83313, '<td valign="top">Very moody. Nice work.</td>', 'Very moody. Nice work.', '2010-02-10 13:24:19.000000', NULL, 1),
(5861916, 852594, 83313, '<td valign="top">The condensation on the cockpit really adds some extra punch to this. Trying to figure out what kind of plane this is. Judging by the shape of the canopy and the perspective you were able to shoot this from, I am guessing this is a Canberra bomber.</td>', 'The condensation on the cockpit really adds some extra punch to this. Trying to figure out what kind of plane this is. Judging by the shape of the canopy and the perspective you were able to shoot this from, I am guessing this is a Canberra bomber.', '2010-02-10 13:27:35.000000', NULL, 1),
(5861922, 852755, 83313, '<td valign="top">A very creative shoehorn effort!</td>', 'A very creative shoehorn effort!', '2010-02-10 13:29:38.000000', NULL, 1),
(5861925, 852750, 83313, '<td valign="top">Well, out of all the chair-on-the-beach entries in this challenge, at least yours is honest in admitting that it doesn''t belong.</td>', 'Well, out of all the chair-on-the-beach entries in this challenge, at least yours is honest in admitting that it doesn''t belong.', '2010-02-10 13:31:52.000000', NULL, 1),
(5861928, 852208, 83313, '<td valign="top">I really ought to knock of points for the overused title. But, then again, I entered one called "Fire in the Sky". I probably shouldn''t throw stones at a glass house, should I?</td>', 'I really ought to knock of points for the overused title. But, then again, I entered one called "Fire in the Sky". I probably shouldn''t throw stones at a glass house, should I?', '2010-02-10 13:34:31.000000', NULL, 1),
