(5866368, 852481, 37529, '<td valign="top">I guess there is a reason you made this OOF but I''m afraid I don''t get it.  I like the soft colors though.</td>', 'I guess there is a reason you made this OOF but I''m afraid I don''t get it.  I like the soft colors though.', '2010-02-14 08:55:01.000000', NULL, 1),
(5866369, 852594, 37529, '<td valign="top">Good perspective.  Sharp and interesting.  My guess is this one will be at least in the top ten.</td>', 'Good perspective.  Sharp and interesting.  My guess is this one will be at least in the top ten.', '2010-02-14 08:57:21.000000', NULL, 1),
(5866372, 852500, 37529, '<td valign="top">Nicely done.  Good perspective on an interesting chair.  The gold pillow sets it off well.</td>', 'Nicely done.  Good perspective on an interesting chair.  The gold pillow sets it off well.', '2010-02-14 08:59:15.000000', NULL, 1),
(5866375, 852673, 37529, '<td valign="top">Good shot.  The ghostly figure is nicely done.</td>', 'Good shot.  The ghostly figure is nicely done.', '2010-02-14 09:01:20.000000', NULL, 1),
(5866377, 852710, 37529, '<td valign="top">Nothing like catching some rays in sub zero weather.  Interesting picture.  I like the hat.</td>', 'Nothing like catching some rays in sub zero weather.  Interesting picture.  I like the hat.', '2010-02-14 09:03:27.000000', NULL, 1),
(5866382, 852054, 37529, '<td valign="top">You will probably get lots of dings on the OOF factor.  Nice composition otherwise.</td>', 'You will probably get lots of dings on the OOF factor.  Nice composition otherwise.', '2010-02-14 09:06:11.000000', NULL, 1),
(5866388, 851990, 37529, '<td valign="top">Nice shot.  The B&amp;W works well.</td>', 'Nice shot.  The B&W works well.', '2010-02-14 09:09:28.000000', NULL, 1),
(5866391, 852715, 37529, '<td valign="top">Bit of a shoehorn I think.  Good concept though.</td>', 'Bit of a shoehorn I think.  Good concept though.', '2010-02-14 09:10:25.000000', NULL, 1),
(5866394, 852755, 37529, '<td valign="top">OK I give up.  Where''s the chair?  Nice macro shot of the toad stools.</td>', 'OK I give up.  Where''s the chair?  Nice macro shot of the toad stools.', '2010-02-14 09:12:22.000000', NULL, 1),
(5866398, 851991, 37529, '<td valign="top">It took me awhile to figure out what this was and I think that is what makes this an excellent shot.</td>', 'It took me awhile to figure out what this was and I think that is what makes this an excellent shot.', '2010-02-14 09:14:22.000000', NULL, 1),
(5866473, 852398, 23484, '<td valign="top">Erie shot. The longer exposure makes the water look like mist.</td>', 'Erie shot. The longer exposure makes the water look like mist.', '2010-02-14 10:32:03.000000', NULL, 1),
(5866475, 852208, 23484, '<td valign="top">Very nice processing. I like the colortone and the gritty feel from the grain.</td>', 'Very nice processing. I like the colortone and the gritty feel from the grain.', '2010-02-14 10:32:46.000000', NULL, 1),
(5866477, 852489, 23484, '<td valign="top">Great. That lens flare gave this a neat feel.</td>', 'Great. That lens flare gave this a neat feel.', '2010-02-14 10:34:05.000000', NULL, 1),
(5866480, 852029, 23484, '<td valign="top">The processing on this makes it look like it came from an old toy camera. Nice job.</td>', 'The processing on this makes it look like it came from an old toy camera. Nice job.', '2010-02-14 10:35:15.000000', NULL, 1),
(5866481, 852595, 23484, '<td valign="top">Now this would have been a great shot for the Perspective challenge. Nice idea.</td>', 'Now this would have been a great shot for the Perspective challenge. Nice idea.', '2010-02-14 10:35:58.000000', NULL, 1),
(5866482, 852256, 23484, '<td valign="top">That chair has certainly seen better days. Nice composition.</td>', 'That chair has certainly seen better days. Nice composition.', '2010-02-14 10:37:05.000000', NULL, 1),
(5866483, 852600, 23484, '<td valign="top">Nice retro style shot.</td>', 'Nice retro style shot.', '2010-02-14 10:37:53.000000', NULL, 1),
(5866484, 852744, 23484, '<td valign="top">You caught this from a great point of view. Nice job.</td>', 'You caught this from a great point of view. Nice job.', '2010-02-14 10:38:58.000000', NULL, 1),
(5866507, 851991, 76335, '<td valign="top">Nice abstract, bold colors, textures.</td>', 'Nice abstract, bold colors, textures.', '2010-02-14 11:36:36.000000', NULL, 1),
(5866512, 852416, 76335, '<td valign="top">Interesting framing. Maybe a bit too much happening, but the attention still seems to be on the writing.</td>', 'Interesting framing. Maybe a bit too much happening, but the attention still seems to be on the writing.', '2010-02-14 11:49:09.000000', NULL, 1),
(5866518, 852100, 76335, '<td valign="top">Nice abstract. I like the textures and the cool muted blues.</td>', 'Nice abstract. I like the textures and the cool muted blues.', '2010-02-14 11:53:31.000000', NULL, 1),
(5866519, 852286, 76335, '<td valign="top">Casual and fun. A good take on the challenge theme.</td>', 'Casual and fun. A good take on the challenge theme.', '2010-02-14 11:53:51.000000', NULL, 1),
(5866520, 852578, 76335, '<td valign="top">The border doesn''t do much for me, but I do like the still life composition and natural light.</td>', 'The border doesn''t do much for me, but I do like the still life composition and natural light.', '2010-02-14 11:54:18.000000', NULL, 1),
(5866522, 852750, 76335, '<td valign="top">All the same, it''s seat I wouldn''t mind having on any given day. Nice rich colors here...</td>', 'All the same, it''s seat I wouldn''t mind having on any given day. Nice rich colors here...', '2010-02-14 11:56:52.000000', NULL, 1),
(5866523, 852401, 76335, '<td valign="top">Simple and effective. Good use of negative space. I like how the chair is facing out of the frame -- a broken rule that works.</td>', 'Simple and effective. Good use of negative space. I like how the chair is facing out of the frame -- a broken rule that works.', '2010-02-14 11:57:24.000000', NULL, 1),
(5866524, 852741, 76335, '<td valign="top">More subtle lighting might have better shown off the textures.</td>', 'More subtle lighting might have better shown off the textures.', '2010-02-14 11:57:46.000000', NULL, 1),
(5866527, 852518, 76335, '<td valign="top">The chair seems secondary to your beautiful posing subject. Nice natural lighting...</td>', 'The chair seems secondary to your beautiful posing subject. Nice natural lighting...', '2010-02-14 12:01:36.000000', NULL, 1),
(5866528, 852628, 76335, '<td valign="top">Nice! I almost missed the feet...</td>', 'Nice! I almost missed the feet...', '2010-02-14 12:02:07.000000', NULL, 1),
(5866535, 852703, 76335, '<td valign="top">I''ve seen the snow blob sitting in quite a few places this week. Cool shot.</td>', 'I''ve seen the snow blob sitting in quite a few places this week. Cool shot.', '2010-02-14 12:09:51.000000', NULL, 1),
(5866537, 852736, 76335, '<td valign="top">There are ways to get a more natural looking grain: <br/><a href="//photoshoptutorials.ws/photoshop-tutorials/photo-effects/natural-film-grain.html" rel="nofollow" target="_blank">//photoshoptutorials.ws/photoshop-tutorials/photo-effects/natural-film-grain.html</a> <br/> <br/>Nice composition...</td>', 'There are ways to get a more natural looking grain: //photoshoptutorials.ws/photoshop-tutorials/photo-effects/natural-film-grain.html  Nice composition...', '2010-02-14 12:12:05.000000', NULL, 1),
(5866539, 852700, 76335, '<td valign="top">I love the point of view here. The natural light is beautiful...</td>', 'I love the point of view here. The natural light is beautiful...', '2010-02-14 12:13:18.000000', NULL, 1),
(5866543, 852481, 67152, '<td valign="top">wonderfully seen</td>', 'wonderfully seen', '2010-02-14 12:21:57.000000', NULL, 1),
(5866548, 852489, 67152, '<td valign="top">almost a chair, almost a living thing</td>', 'almost a chair, almost a living thing', '2010-02-14 12:26:02.000000', NULL, 1),
(5866549, 852518, 67152, '<td valign="top">a classic</td>', 'a classic', '2010-02-14 12:26:47.000000', NULL, 1),
(5866553, 851734, 67152, '<td valign="top">love it!</td>', 'love it!', '2010-02-14 12:29:22.000000', NULL, 1),
(5866555, 852366, 76335, '<td valign="top">Nice nostalgic feel to this. Is that a theater chair?</td>', 'Nice nostalgic feel to this. Is that a theater chair?', '2010-02-14 12:36:16.000000', NULL, 1),
(5866556, 852660, 76335, '<td valign="top">More about the cat than the chair, but a nice image anyway.</td>', 'More about the cat than the chair, but a nice image anyway.', '2010-02-14 12:36:38.000000', NULL, 1),
(5866557, 851457, 76335, '<td valign="top">A bit of a blue/purple cast in this, but a nice moment anyway.</td>', 'A bit of a blue/purple cast in this, but a nice moment anyway.', '2010-02-14 12:37:40.000000', NULL, 1),
(5866558, 852122, 76335, '<td valign="top">Almost feels like a diptych -- the chair is a nice relief from the chaos on the left.</td>', 'Almost feels like a diptych -- the chair is a nice relief from the chaos on the left.', '2010-02-14 12:40:04.000000', NULL, 1),
(5866559, 852739, 76335, '<td valign="top">Nice rhythm here, and feeling of anticipation and perhaps even conformance. Processing might be a bit heavy (Topaz?) but that''s a personal quibble. Overall, very nice.</td>', 'Nice rhythm here, and feeling of anticipation and perhaps even conformance. Processing might be a bit heavy (Topaz?) but that''s a personal quibble. Overall, very nice.', '2010-02-14 12:41:16.000000', NULL, 1),
(5866561, 852500, 76335, '<td valign="top">It seems slightly tilted, but I don''t think it bothers me. Nice imposing angle.</td>', 'It seems slightly tilted, but I don''t think it bothers me. Nice imposing angle.', '2010-02-14 12:42:20.000000', NULL, 1),
(5866584, 852755, 100831, '<td valign="top">those are not chairs (he he he)</td>', 'those are not chairs (he he he)', '2010-02-14 13:26:50.000000', NULL, 1),
(5866602, 851828, 76335, '<td valign="top">I like the simple lines and solid colors.</td>', 'I like the simple lines and solid colors.', '2010-02-14 13:58:00.000000', NULL, 1),
(5866642, 852755, 36133, '<td valign="top">Heh!Puns/wordplay are a favorite pastime. I like the well-controlled dof and very slightly oversaturated colors in this image.</td>', 'Heh!Puns/wordplay are a favorite pastime. I like the well-controlled dof and very slightly oversaturated colors in this image.', '2010-02-14 15:11:42.000000', NULL, 1),
(5866643, 852454, 36133, '<td valign="top">LOL! Well, yes, it does have a chair. No one said it had to make any sense. On balance (heh!) it works well. 8</td>', 'LOL! Well, yes, it does have a chair. No one said it had to make any sense. On balance (heh!) it works well. 8', '2010-02-14 15:15:53.000000', NULL, 1),
(5866649, 852621, 36133, '<td valign="top">So cute! Brings back fond memories of cocker spaniels I used to own. Such an expressive face.</td>', 'So cute! Brings back fond memories of cocker spaniels I used to own. Such an expressive face.', '2010-02-14 15:19:03.000000', NULL, 1),
(5866650, 852696, 36133, '<td valign="top">Very nice still life. I like the color palette.</td>', 'Very nice still life. I like the color palette.', '2010-02-14 15:19:43.000000', NULL, 1),
(5866651, 852742, 36133, '<td valign="top">Picture is OK. Another point added for humor.</td>', 'Picture is OK. Another point added for humor.', '2010-02-14 15:20:46.000000', NULL, 1),
(5866652, 852732, 36133, '<td valign="top">Fortunate to have a red car in the reflection!</td>', 'Fortunate to have a red car in the reflection!', '2010-02-14 15:22:36.000000', NULL, 1),
(5866653, 852418, 36133, '<td valign="top">I like the colors, but the composition leaves my eye looking for something to settle on</td>', 'I like the colors, but the composition leaves my eye looking for something to settle on', '2010-02-14 15:24:13.000000', NULL, 1),
(5866654, 852507, 36133, '<td valign="top">Clever and well done. The b/w conversion is, of course, entirely appropriate.</td>', 'Clever and well done. The b/w conversion is, of course, entirely appropriate.', '2010-02-14 15:25:11.000000', NULL, 1),
(5866655, 852715, 36133, '<td valign="top">So, the picture was <i>taken</i> from a rocking chair? The chair is not in the image, but I guess it''s <i>essence</i> (rocking is there. I like the idea and the image is pretty cool.</td>', 'So, the picture was taken from a rocking chair? The chair is not in the image, but I guess it''s essence (rocking is there. I like the idea and the image is pretty cool.', '2010-02-14 15:28:19.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5866719, 852617, 97225, '<td valign="top">I love the warped perspective which makes the buildings loom in over the poor insignificant little chair. It''s no wonder that chair is vacant. It doesn''t look like a very friendly environment. Well captured.</td>', 'I love the warped perspective which makes the buildings loom in over the poor insignificant little chair. It''s no wonder that chair is vacant. It doesn''t look like a very friendly environment. Well captured.', '2010-02-14 17:24:51.000000', NULL, 1),
(5866720, 852586, 97225, '<td valign="top">The quick brown fox jumps over the lazy...chair! How original.</td>', 'The quick brown fox jumps over the lazy...chair! How original.', '2010-02-14 17:26:14.000000', NULL, 1),
(5866722, 852759, 97225, '<td valign="top">Beautiful. I''m sure that chair is waiting for me. (I wish)</td>', 'Beautiful. I''m sure that chair is waiting for me. (I wish)', '2010-02-14 17:28:00.000000', NULL, 1),
(5866723, 852518, 97225, '<td valign="top">Love the light - and the model.</td>', 'Love the light - and the model.', '2010-02-14 17:30:54.000000', NULL, 1),
(5866724, 852681, 97225, '<td valign="top">Funny.</td>', 'Funny.', '2010-02-14 17:32:42.000000', NULL, 1),
