(5866741, 852635, 97225, '<td valign="top">Wow!</td>', 'Wow!', '2010-02-14 17:42:45.000000', NULL, 1),
(5866742, 852405, 97225, '<td valign="top">How cute is he? Lovely shot.</td>', 'How cute is he? Lovely shot.', '2010-02-14 17:43:26.000000', NULL, 1),
