(5866748, 852507, 97225, '<td valign="top">Nice perspective and patterns - good title.</td>', 'Nice perspective and patterns - good title.', '2010-02-14 17:51:07.000000', NULL, 1),
(5866754, 852100, 102278, '<td valign="top">Great abstract. In my top five of the challenge. 9.</td>', 'Great abstract. In my top five of the challenge. 9.', '2010-02-14 18:02:26.000000', NULL, 1),
(5866755, 852489, 102278, '<td valign="top">Wonderful ghostly image. In my top five of the challenge. 9.</td>', 'Wonderful ghostly image. In my top five of the challenge. 9.', '2010-02-14 18:02:47.000000', NULL, 1),
(5866756, 852681, 102278, '<td valign="top">Fantastic. I love the combination of frantic blur and sturdy sharp chair. In my top five of the challenge. 9.</td>', 'Fantastic. I love the combination of frantic blur and sturdy sharp chair. In my top five of the challenge. 9.', '2010-02-14 18:03:35.000000', NULL, 1),
(5866759, 851844, 105457, '<td valign="top">A great shot,but unfortunately with the wrong white balance. The pink tones in the skin could be corrected with the tweaking of the white balance. Still, a very good photo!</td>', 'A great shot,but unfortunately with the wrong white balance. The pink tones in the skin could be corrected with the tweaking of the white balance. Still, a very good photo!', '2010-02-14 18:24:07.000000', NULL, 1),
