(5866768, 852286, 51747, '<td valign="top">Made me smile. Nice idea.</td>', 'Made me smile. Nice idea.', '2010-02-14 18:40:45.000000', NULL, 1),
(5866769, 851990, 51747, '<td valign="top">Very nice.</td>', 'Very nice.', '2010-02-14 18:41:59.000000', NULL, 1),
